#!/bin/bash
set -e
APP=/root/opslabs
ts=$(date +%Y%m%d-%H%M%S)
mkdir -p "$APP/app/routes" "$APP/app/templates/admin"
cp "$APP/app/routes/admin.py" "$APP/app/routes/admin.py.bak.$ts" 2>/dev/null || true
cp "$APP/app/templates/admin/user_form.html" "$APP/app/templates/admin/user_form.html.bak.$ts" 2>/dev/null || true

base64 -d << 'ADMIN2_B64' > "$APP/app/routes/admin.py"

ADMIN2_B64

base64 -d << 'USERFORM_B64' > "$APP/app/templates/admin/user_form.html"

USERFORM_B64

python3 -m py_compile "$APP/app/routes/admin.py"
systemctl restart opslabs-app.service
sleep 2
systemctl status opslabs-app.service --no-pager -l | head -15
journalctl -u opslabs-app.service -n 15 --no-pager
